import os, pathlib, subprocess, json
GIT=os.environ.get('OPSFORGE_GIT','git')
def git(repo,*args,check=True):
    p=subprocess.run([GIT,'-C',str(repo),*args],capture_output=True,text=True,encoding='utf-8',check=check)
    return p.stdout.strip()
def execute(repo,remote_path,name,commit_id):
    target=git(repo,'rev-parse',commit_id+'^{commit}');ref='refs/tags/'+name
    p=subprocess.run([GIT,'-C',str(repo),'rev-parse','--verify',ref],capture_output=True,text=True)
    local_exists=p.returncode==0
    if local_exists:
        if git(repo,'rev-parse',ref+'^{commit}')!=target:raise ValueError('local tag differs')
        if git(repo,'cat-file','-t',ref)!='tag':raise ValueError('annotated tag required')
    rows={line.split()[1]:line.split()[0] for line in git(repo,'ls-remote','--tags',str(remote_path),ref,ref+'^{}').splitlines()}
    if rows:
        if rows.get(ref+'^{}',rows.get(ref))!=target:raise ValueError('remote tag immutable')
        return rows[ref]
    if not local_exists:git(repo,'tag','-a',name,target,'-m','release '+name)
    git(repo,'push',str(remote_path),ref+':'+ref);return git(repo,'rev-parse',ref)
```

实现说明：实现 execute(repo,remote_path,name,commit_id)：若本地/远端同名标签不存在则创建附注标签并推送；存在且剥离目标相同则幂等返回远端tag对象ID；任一同名标签目标不同必须拒绝，不force、不移动本地或远端标签。

原理补充（保留原题）：
移动同名标签让不同克隆和缓存对同一版本名解析到不同对象，破坏可复现与审计。应保留旧标签，发布新的明确版本并记录废弃说明，部署以完整提交或制品摘要固定；标签保护规则需要服务端执行。

