import os, pathlib, subprocess, json
GIT=os.environ.get('OPSFORGE_GIT','git')
def git(repo,*args,check=True):
    p=subprocess.run([GIT,'-C',str(repo),*args],capture_output=True,text=True,encoding='utf-8',check=check)
    return p.stdout.strip()
def execute(repo,a,b):
    def patch(rev):
        data=subprocess.run([GIT,'-C',str(repo),'show','--pretty=format:','--no-ext-diff',rev],capture_output=True,check=True).stdout
        p=subprocess.run([GIT,'patch-id','--stable'],input=data,capture_output=True,check=True)
        return p.stdout.split()[0] if p.stdout.split() else None
    return {'patch_equal':patch(a)==patch(b),'commit_equal':git(repo,'rev-parse',a)==git(repo,'rev-parse',b)}
```

