import os,sys,pathlib,subprocess,tempfile,json,shutil
sys.path.insert(0,str(pathlib.Path.cwd()))
import task
GIT=os.environ.get('OPSFORGE_GIT','git')
def g(repo,*args,check=True):
    p=subprocess.run([GIT,'-C',str(repo),*args],capture_output=True,text=True,encoding='utf-8')
    if check and p.returncode: raise AssertionError((args,p.returncode,p.stdout,p.stderr))
    return p.stdout.strip()
def put(repo,name,content):
    p=pathlib.Path(repo)/name;p.parent.mkdir(parents=True,exist_ok=True);p.write_text(content,encoding='utf-8',newline='')
def init(name='repo',bare=False):
    p=pathlib.Path(name).resolve();p.mkdir(parents=True,exist_ok=True)
    g(p,'init','-b','main',*(['--bare'] if bare else []))
    g(p,'config','user.name','Exercise Author');g(p,'config','user.email','exercise@example.invalid')
    g(p,'config','core.autocrlf','false');g(p,'config','commit.gpgsign','false')
    return p
def commit(repo,files,msg='fixture'):
    for name,content in files.items(): put(repo,name,content)
    g(repo,'add','--all');g(repo,'commit','-m',msg)
    return g(repo,'rev-parse','HEAD')
def before(repo):
    return (g(repo,'rev-parse','HEAD'),g(repo,'diff','--binary'),g(repo,'diff','--cached','--binary'),g(repo,'status','--porcelain=v1','--untracked-files=all'))
r=init();commit(r,{'base':'b'});bad=commit(r,{'bad':'wrong'});later=commit(r,{'good':'keep'});new=task.execute(r,bad);assert not (r/'bad').exists() and (r/'good').read_text()=='keep';assert g(r,'rev-parse',new+'^')==later and g(r,'rev-list','--count','HEAD')=='4';g(r,'merge-base','--is-ancestor',bad,new)

