import os, pathlib, subprocess, json
GIT=os.environ.get('OPSFORGE_GIT','git')
def git(repo,*args,check=True):
    p=subprocess.run([GIT,'-C',str(repo),*args],capture_output=True,text=True,encoding='utf-8',check=check)
    return p.stdout.strip()
def execute(repo):
    ours=json.loads(git(repo,'show',':2:config.json'));theirs=json.loads(git(repo,'show',':3:config.json'))
    if ours['name']!=theirs['name']:raise ValueError('name conflict')
    result={**ours,'timeout':theirs['timeout']};(pathlib.Path(repo)/'config.json').write_text(json.dumps(result,sort_keys=True)+'\n',encoding='utf-8');git(repo,'add','config.json');git(repo,'commit','-m','combine audit and timeout');return git(repo,'rev-parse','HEAD')

